// Prepare signed authentication headers for Convex HTTP request
const crypto = require('crypto');

const timestamp = Date.now().toString();
const secret = $env.LENDLOOP_WEBHOOK_SECRET || 'lendloop_shared_hmac_secret_2026';
const payloadToSign = `overdue-loans:${timestamp}`;

const hmac = crypto.createHmac('sha256', secret);
hmac.update(payloadToSign);
const signature = hmac.digest('hex');

const convexUrl = ($env.CONVEX_SITE_URL || 'http://localhost:3000').replace(/\/+$/, '');

return [{
  json: {
    targetUrl: `${convexUrl}/overdue-loans`,
    timestamp,
    signature,
    secret
  }
}];

// Process array of overdue loans & compute idempotent write-back signatures
const crypto = require('crypto');

const items = $input.all();
const results = [];
const secret = $env.LENDLOOP_WEBHOOK_SECRET || 'lendloop_shared_hmac_secret_2026';
const convexUrl = ($env.CONVEX_SITE_URL || 'http://localhost:3000').replace(/\/+$/, '');
const todayStr = new Date().toISOString().split('T')[0];

for (const item of items) {
  const loan = item.json;
  if (!loan || !loan.loanId) continue;

  // Deterministic Idempotency Key: prevents duplicate reminders on retries
  const idempotencyKey = `overdue-${loan.loanId}-${todayStr}`;

  const writebackBody = {
    loanId: loan.loanId,
    idempotencyKey,
    status: 'sent',
    details: `Automated overdue reminder sent to ${loan.borrowerEmail} for tool ${loan.toolName} (${loan.daysOverdue} days overdue)`
  };

  const bodyString = JSON.stringify(writebackBody);
  const hmac = crypto.createHmac('sha256', secret);
  hmac.update(bodyString);
  const writebackSignature = hmac.digest('hex');

  results.push({
    json: {
      loanId: loan.loanId,
      toolName: loan.toolName,
      borrowerEmail: loan.borrowerEmail,
      borrowerName: loan.borrowerName,
      endDate: loan.endDate,
      daysOverdue: loan.daysOverdue,
      idempotencyKey,
      writebackUrl: `${convexUrl}/record-reminder`,
      writebackBody,
      writebackSignature
    }
  });
}

return results;

// Simulate / Dispatch Email Reminder to Borrower
const loan = $input.item.json;

console.log(`[Overdue Reminder] Sending overdue notice to: ${loan.borrowerEmail}`);
console.log(`Tool: ${loan.toolName} was due on ${loan.endDate} (${loan.daysOverdue} days ago)`);

return [{
  json: {
    ...loan,
    reminderDispatched: true,
    dispatchedAt: new Date().toISOString()
  }
}];
